INSERT OR IGNORE INTO posts (id, slug, title, category, category_slug, filters_json, date, date_display, read_time, author, image, image_alt, excerpt, content_json, status, created_at, updated_at) VALUES ('post-chien-dich-lam-sach-ven-ho-tan-xa-mua-thu-2026', 'chien-dich-lam-sach-ven-ho-tan-xa-mua-thu-2026', 'Cuối Tuần Xanh #18 Hồ Tân Xã: Thu gom 180 kg rác', 'HolaGreen · Sạch', 'moi-truong', '["sach"]', '2026-11-08', '08/11/2026', '2 phút đọc', 'Ban Điều Phối HolaRise', '/assets/images/activity-environment.jpg', 'Các bạn trẻ Cộng đồng HolaRise đeo găng tay phân loại rác nhựa tại Tân Xã, Hòa Lạc trong buổi sáng', '52 thanh niên, sinh viên và học sinh đã cùng làm sạch 2km ven hồ Tân Xã và phân loại 180 kg rác trong sáng Chủ Nhật.', '["6h45 sáng Chủ Nhật 08/11, 52 bạn thanh niên, sinh viên và học sinh đã có mặt tại điểm hẹn ven hồ Tân Xã, Hòa Lạc để khởi động chiến dịch Cuối Tuần Xanh #18 thuộc [chương trình môi trường HolaGreen](/hoat-dong/#moi-truong).", "Ban Điều Phối chia thành 10 nhóm nhỏ để người mới đi lần đầu nhanh chóng làm quen, tương tự cách sắp xếp ở [lịch hoạt động cuối tuần tại Hòa Lạc](/workshop/). Mỗi nhóm được trang bị găng tay vải, kẹp gắp rác và túi phân loại riêng cho nhựa tái chế.", "Sau 2 giờ làm việc dọc 2 km bờ hồ Tân Xã, cả đoàn thu gom 180 kg rác thải, trong đó tách riêng 35 kg chai nhựa và vỏ lon bàn giao cho điểm tái chế địa phương.", "Hơn cả một tuyến đường sạch đẹp, buổi sáng cuối tuần mang lại những người bạn mới chân thành và tinh thần Small Beginnings, Great Impact gắn với [sứ mệnh và 4 giá trị của HolaRise](/gioi-thieu/)."]', 'published', '2026-11-21T09:40:43Z', '2026-11-21T09:40:43Z');
INSERT OR IGNORE INTO posts (id, slug, title, category, category_slug, filters_json, date, date_display, read_time, author, image, image_alt, excerpt, content_json, status, created_at, updated_at) VALUES ('post-workshop-gieo-mam-tu-te-lan-toa-loi-song-tich-cuc', 'workshop-gieo-mam-tu-te-lan-toa-loi-song-tich-cuc', 'Workshop HolaHeart #14: Lòng biết ơn gia đình', 'HolaHeart · Biết ơn & Tử tế', 'workshop', '["biet-on", "tu-te"]', '2026-10-25', '25/10/2026', '2 phút đọc', 'Ban Nội Dung HolaRise', '/assets/images/activity-workshop.jpg', 'Thanh niên, sinh viên và học sinh tham gia buổi Workshop HolaHeart tại Tân Xã, Hòa Lạc', '38 bạn trẻ tại Hòa Lạc cùng lắng nghe câu chuyện về lòng biết ơn cha mẹ – thầy cô và tự tay làm thiệp lá khô gửi người thân.', '["Chiều Chủ Nhật 25/10 tại Tân Xã, Hòa Lạc, 38 học sinh và sinh viên đã tham dự buổi thứ 14 trong [chuỗi Workshop giá trị sống HolaHeart](/workshop/) với chủ đề \"Lòng Biết Ơn – Cội Nguồn Của Nhân Cách Đẹp\".", "Không gian buổi gặp gỡ mở đầu bằng những câu chuyện đời thường xúc động về sự hy sinh thầm lặng của cha mẹ, sự dìu dắt của thầy cô và [câu chuyện cộng đồng thanh niên Hòa Lạc](/gioi-thieu/).", "Ở phần thực hành, mỗi bạn tự tay làm một tấm thiệp ép lá khô viết lời cảm ơn gửi về gia đình, tiếp nối hành trình tử tế của [các chiến dịch thiện nguyện HolaRise](/hoat-dong/#workshop)."]', 'published', '2026-11-21T09:40:43Z', '2026-11-21T09:40:43Z');
INSERT OR IGNORE INTO posts (id, slug, title, category, category_slug, filters_json, date, date_display, read_time, author, image, image_alt, excerpt, content_json, status, created_at, updated_at) VALUES ('post-nhip-cau-yeu-thuong-trao-tu-sach-thach-that', 'nhip-cau-yeu-thuong-trao-tu-sach-thach-that', 'HolaConnect: Trao 152 sách cho thiếu nhi Hòa Lạc', 'HolaConnect · Sẻ chia', 'cong-dong', '["se-chia"]', '2026-10-04', '04/10/2026', '2 phút đọc', 'Ban Phụng Sự HolaRise', '/assets/images/activity-community.jpg', 'Tình nguyện viên Cộng đồng HolaRise đọc sách truyện và tặng quà học tập cùng các em nhỏ tại Tân Xã, Hòa Lạc', '152 cuốn sách thiếu nhi và quà học tập do sinh viên Hòa Lạc đóng góp đã được trao tận tay các em nhỏ tại Tân Xã.', '["Đầu tháng 10, Cộng đồng HolaRise phát động đợt quyên góp \"Tủ Sách Thanh Niên Gửi Thiếu Nhi Hòa Lạc\" thuộc [chương trình phụng sự HolaConnect](/hoat-dong/#cong-dong) và nhận được 152 cuốn sách truyện, khoa học thường thức từ học sinh, sinh viên.", "Mỗi cuốn sách đều được bọc cẩn thận kèm lời chúc viết tay ở trang đầu. Trong buổi sáng trao tặng, tình nguyện viên cùng các em nhỏ đọc sách, chơi đố vui môi trường và chuẩn bị cho [các buổi workshop và giao lưu sắp tới](/workshop/).", "Toàn bộ danh mục sách và hình ảnh được lưu trữ công khai theo [nguyên tắc hoạt động minh bạch](/gioi-thieu/#minh-bach). Bạn có thể [đăng ký đồng hành đợt trao sách tiếp theo](/tham-gia/) ngay trên website."]', 'published', '2026-11-21T09:40:43Z', '2026-11-21T09:40:43Z');
INSERT OR IGNORE INTO events (id, kind, type, filters_json, date, date_display, time, location, fee, seats, title, summary, highlights_json, participants, image, image_alt, status, sort_order, created_at, updated_at) VALUES ('ws-long-biet-on-va-song-xanh', 'upcoming', 'HolaHeart · Biết ơn & Tử tế', '["biet-on", "tu-te"]', '2026-11-29', 'CN, 29/11/2026', '08:30 – 11:00', 'Tân Xã, Hòa Lạc', 'Miễn phí', 'Còn 18/40 chỗ', 'Workshop: Lòng Biết Ơn & Sự Tử Tế Giữa Đời Thường', 'Cùng sẻ chia về lòng biết ơn cha mẹ – thầy cô, tự tay viết thiệp tri ân và tái chế lọ thủy tinh thành chậu cây xanh.', '["Sẻ chia lòng biết ơn", "Tái chế chậu cây xanh", "Viết thiệp tri ân"]', '', '/assets/images/activity-workshop.jpg', 'Các bạn trẻ Cộng đồng HolaRise tham gia buổi Workshop chia sẻ giá trị sống cao đẹp tại Tân Xã, Hòa Lạc', 'published', 0, '2026-11-21T09:40:43Z', '2026-11-21T09:40:43Z');
